"use client";

import * as React from "react";

import {
  type GstinResult,
  normalizeGstin,
  validateGstin,
} from "../../lib/gstin";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

export interface GSTINInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: GstinResult) => void;
  validateOn?: "blur" | "change";
  /** Show the resolved state once the GSTIN validates. Default `true`. */
  showState?: boolean;
  /**
   * A PAN to cross-check against. A GSTIN embeds its holder's PAN, so if you
   * already collected one you can catch a mismatched pair for free.
   */
  expectedPan?: string;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function GSTINInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showState = true,
  expectedPan,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: GSTINInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `gstin-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<GstinResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validateGstin,
    transform: (raw) =>
      normalizeGstin(raw)
        .replace(/[^A-Z0-9]/g, "")
        .slice(0, 15),
    validateOn,
  });

  const panMismatch =
    field.result.valid &&
    expectedPan &&
    field.result.pan !== expectedPan.replace(/\s/g, "").toUpperCase()
      ? `This GSTIN belongs to PAN ${field.result.pan}, not ${expectedPan.toUpperCase()}.`
      : undefined;

  const state =
    showState && field.result.valid ? field.result.state : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? panMismatch ?? description}
      tone={field.error || panMismatch ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          placeholder={props.placeholder ?? "27ABCDE1234F1Z5"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error || panMismatch)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error || panMismatch),
              success: field.success && !panMismatch,
            }),
            "uppercase tracking-[0.1em]",
            state && "pr-36",
            className,
          )}
        />
        {state && !panMismatch && <FieldBadge>{state}</FieldBadge>}
      </div>
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * GSTIN (Goods and Services Tax Identification Number) validation.
 *
 * 15 characters, and unusually for Indian identifiers the checksum *is*
 * published, so this can be fully validated offline:
 *
 *   ┌──┬──────────┬─┬─┬─┐
 *   │01│AAAAA1111A│1│Z│5│
 *   └──┴──────────┴─┴─┴─┘
 *     │      │      │ │ └─ 15  check character (mod-36)
 *     │      │      │ └─── 14  'Z' by convention
 *     │      │      └───── 13  entity number for that PAN in that state
 *     │      └──────────── 3-12 the holder's PAN
 *     └─────────────────── 1-2 state code
 *
 * Because the PAN is embedded, a GSTIN and a PAN can be cross-checked against
 * each other — which is the most useful thing this module does.
 */

import { type PanResult, validatePan } from "./pan";

const CHARSET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const GSTIN_RE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]{3}$/;

/** State/UT codes as used in the first two characters. */
export const GST_STATE_CODES: Readonly<Record<string, string>> = {
  "01": "Jammu & Kashmir",
  "02": "Himachal Pradesh",
  "03": "Punjab",
  "04": "Chandigarh",
  "05": "Uttarakhand",
  "06": "Haryana",
  "07": "Delhi",
  "08": "Rajasthan",
  "09": "Uttar Pradesh",
  "10": "Bihar",
  "11": "Sikkim",
  "12": "Arunachal Pradesh",
  "13": "Nagaland",
  "14": "Manipur",
  "15": "Mizoram",
  "16": "Tripura",
  "17": "Meghalaya",
  "18": "Assam",
  "19": "West Bengal",
  "20": "Jharkhand",
  "21": "Odisha",
  "22": "Chhattisgarh",
  "23": "Madhya Pradesh",
  "24": "Gujarat",
  "25": "Daman & Diu (pre-merger)",
  "26": "Dadra & Nagar Haveli and Daman & Diu",
  "27": "Maharashtra",
  "28": "Andhra Pradesh (pre-bifurcation)",
  "29": "Karnataka",
  "30": "Goa",
  "31": "Lakshadweep",
  "32": "Kerala",
  "33": "Tamil Nadu",
  "34": "Puducherry",
  "35": "Andaman & Nicobar Islands",
  "36": "Telangana",
  "37": "Andhra Pradesh",
  "38": "Ladakh",
  "97": "Other Territory",
  "99": "Centre Jurisdiction",
};

/**
 * The published GSTIN check character: weights alternate 1 and 2 across the
 * first 14 characters, each product is folded (quotient + remainder, base 36),
 * and the check is whatever brings the total to a multiple of 36.
 */
export function gstinCheckChar(first14: string): string | null {
  if (first14.length !== 14) return null;
  let sum = 0;
  for (let i = 0; i < 14; i++) {
    const value = CHARSET.indexOf(first14[i]);
    if (value === -1) return null;
    const product = value * (i % 2 === 0 ? 1 : 2);
    sum += Math.floor(product / 36) + (product % 36);
  }
  return CHARSET[(36 - (sum % 36)) % 36];
}

export type GstinErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "unknown_state"
  | "bad_checksum"
  | "pan_mismatch";

export interface GstinResult {
  valid: boolean;
  normalized: string;
  stateCode?: string;
  state?: string;
  /** Characters 3–12: the holder's PAN. */
  pan?: string;
  panDetails?: PanResult;
  /** 13th character — which registration this is for that PAN in that state. */
  entityNumber?: string;
  error?: { code: GstinErrorCode; message: string };
}

function fail(
  code: GstinErrorCode,
  message: string,
  normalized: string,
): GstinResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeGstin(input: string): string {
  return input.replace(/\s/g, "").toUpperCase();
}

export function validateGstin(input: string): GstinResult {
  const gstin = normalizeGstin(input);

  if (!input.trim()) return fail("empty", "Enter a GSTIN.", gstin);
  if (gstin.length !== 15) {
    return fail(
      "wrong_length",
      `A GSTIN is 15 characters — ${gstin.length} so far.`,
      gstin,
    );
  }
  if (!GSTIN_RE.test(gstin)) {
    return fail(
      "bad_shape",
      "A GSTIN looks like 27ABCDE1234F1Z5 — state code, PAN, then three more.",
      gstin,
    );
  }

  const stateCode = gstin.slice(0, 2);
  const state = GST_STATE_CODES[stateCode];
  if (!state) {
    return fail(
      "unknown_state",
      `“${stateCode}” isn't a valid state code.`,
      gstin,
    );
  }

  const expected = gstinCheckChar(gstin.slice(0, 14));
  if (expected !== gstin[14]) {
    return fail(
      "bad_checksum",
      "That GSTIN failed its checksum — check for a typo.",
      gstin,
    );
  }

  const pan = gstin.slice(2, 12);
  const panDetails = validatePan(pan);
  if (!panDetails.valid) {
    return fail(
      "pan_mismatch",
      "The PAN embedded in this GSTIN isn't itself valid.",
      gstin,
    );
  }

  return {
    valid: true,
    normalized: gstin,
    stateCode,
    state,
    pan,
    panDetails,
    entityNumber: gstin[12],
  };
}

/** True when a GSTIN embeds the given PAN. Cheap cross-check for onboarding. */
export function gstinMatchesPan(gstin: string, pan: string): boolean {
  const g = validateGstin(gstin);
  if (!g.valid || !g.pan) return false;
  return g.pan === pan.replace(/\s/g, "").toUpperCase();
}

/**
 * PAN (Permanent Account Number) validation.
 *
 * Format is `AAAAA9999A` — five letters, four digits, one letter.
 *
 * The two letters worth understanding:
 *   - 4th character encodes the holder type (P = individual, C = company, …).
 *   - 5th character is the first letter of the surname for an individual, or of
 *     the entity name otherwise.
 *
 * The 10th character *is* a check digit, but the Income Tax Department has
 * never published the algorithm. Anyone claiming to verify a PAN checksum
 * offline is guessing. We validate structure only and say so — real
 * verification needs the NSDL/Protean or Income Tax verification API.
 */

const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;

export type PanHolderType =
  | "Individual"
  | "Company"
  | "Hindu Undivided Family"
  | "Association of Persons"
  | "Body of Individuals"
  | "Government"
  | "Artificial Juridical Person"
  | "Local Authority"
  | "Firm / LLP"
  | "Trust";

const HOLDER_TYPES: Readonly<Record<string, PanHolderType>> = {
  P: "Individual",
  C: "Company",
  H: "Hindu Undivided Family",
  A: "Association of Persons",
  B: "Body of Individuals",
  G: "Government",
  J: "Artificial Juridical Person",
  L: "Local Authority",
  F: "Firm / LLP",
  T: "Trust",
};

export type PanErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "bad_holder_type";

export interface PanResult {
  valid: boolean;
  /** Uppercased, whitespace stripped. */
  normalized: string;
  /** Decoded from the 4th character, when recognised. */
  holderType?: PanHolderType;
  /** First letter of the surname / entity name (5th character). */
  nameInitial?: string;
  error?: { code: PanErrorCode; message: string };
}

function fail(
  code: PanErrorCode,
  message: string,
  normalized: string,
): PanResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizePan(input: string): string {
  return input.replace(/\s/g, "").toUpperCase();
}

export function validatePan(input: string): PanResult {
  const pan = normalizePan(input);

  if (!input.trim()) return fail("empty", "Enter a PAN.", pan);
  if (pan.length !== 10) {
    return fail(
      "wrong_length",
      `A PAN is 10 characters — ${pan.length} so far.`,
      pan,
    );
  }
  if (!PAN_RE.test(pan)) {
    return fail(
      "bad_shape",
      "A PAN looks like ABCDE1234F — five letters, four digits, one letter.",
      pan,
    );
  }

  const holderType = HOLDER_TYPES[pan[3]];
  if (!holderType) {
    return fail(
      "bad_holder_type",
      `“${pan[3]}” isn't a valid 4th character — it encodes the holder type.`,
      pan,
    );
  }

  return { valid: true, normalized: pan, holderType, nameInitial: pan[4] };
}

/** Just the holder type for a 4th character, if you need it standalone. */
export function panHolderType(char: string): PanHolderType | undefined {
  return HOLDER_TYPES[char.toUpperCase()];
}

/** `ABCDE1234F` → `ABCXXXXX4F`. For display and logs. */
export function maskPan(input: string): string {
  const pan = normalizePan(input);
  if (pan.length !== 10) return pan.replace(/./g, "X");
  return `${pan.slice(0, 3)}XXXXX${pan.slice(8)}`;
}
